//! Private currentSourceG2 literalH5647 six qualified terrain nine genuine endpoints/four one-cell Source-FLATS pairs; noWorld.
use std::{collections::{BTreeMap,BTreeSet},fs,io::Write,path::Path};
use raptor_replica::{assets::{Catalog,Sprite},content::Registry,hd::{HdAssets,OriginalDetailCells,OriginalPalette},render::{Canvas,upscale},terrain_hd::{logical_sprite,selected_art,TerrainHd,Replacement,RetainedOriginalPlacement,PaletteConstraintPlacement,OverlayResult}};
use serde_json::{Value,json};
#[derive(Clone)]struct Layer{image:Sprite,retained:Option<OriginalDetailCells>,domain:Option<OriginalPalette>,record:Value}
fn read(p:&Path)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn id(v:&Value)->u32{u32::from_str_radix(v.as_str().unwrap(),16).unwrap()}
fn class(v:u16)->u8{match v{0..=239=>0,240..=244=>1,245..=249=>2,_=>v as u8}}
fn gz(b:&[u8])->Vec<u8>{let mut z=flate2::write::GzEncoder::new(Vec::new(),flate2::Compression::default());z.write_all(b).unwrap();z.finish().unwrap()}
fn emit(out:&Path,name:&str,image:&Sprite,pal:&[[u8;3];256])->Value{let mut b=Vec::new();let mut c=Vec::new();let mut ppm=format!("P6\n{} {}\n255\n",image.width,image.height).into_bytes();for &v in &image.pixels{assert!(v<256);b.extend(v.to_le_bytes());c.push(class(v));ppm.extend(pal[v as usize]);}let ip=format!("{name}.indices-u16le.gz");let cp=format!("{name}.classes-u8.gz");let rp=format!("{name}.ppm.gz");fs::write(out.join(&ip),gz(&b)).unwrap();fs::write(out.join(&cp),gz(&c)).unwrap();fs::write(out.join(&rp),gz(&ppm)).unwrap();json!({"width":image.width,"height":image.height,"indexed":ip,"classes":cp,"PPM":rp})}
// Exact public frame metadata is checked before accepting trusted details/domains.
fn metadata_stage(frame:&Value,retained:&Option<OriginalDetailCells>,domain:&Option<OriginalPalette>){
 let expected:Vec<[u32;2]>=frame.get("original_detail_cells").and_then(|v|v.as_array()).map(|v|v.iter().map(|p|[p[0].as_u64().unwrap()as u32,p[1].as_u64().unwrap()as u32]).collect()).unwrap_or_default();
 assert_eq!(retained.as_ref().map(|d|d.cells()).unwrap_or(&[]),expected.as_slice(),"trusted details match full native frame");
 let opted=frame.get("palette_constraint").is_some_and(|v|!v.is_null());
 assert_eq!(domain.is_some(),opted,"foreign/native palette domain must not be discarded");
 if opted{assert_eq!(frame["palette_constraint"],"original-painted-ordinary-v1");}
}
fn bank_indices(bank:&Value,asset:u32,scale:usize)->Vec<u16>{
 let row=bank.as_array().unwrap().iter().find(|r|id(&r["asset"])==asset).unwrap();
 let rec=row["scales"].as_array().unwrap().iter().find(|r|r["scale"].as_u64()==Some(scale as u64)).unwrap();
 assert_eq!([rec["width"].as_u64().unwrap(),rec["height"].as_u64().unwrap()],[(32*scale)as u64,(32*scale)as u64]);
 rec["indices"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u16).collect()
}




fn support(ids:&[u32],own:&BTreeSet<u32>,active:&BTreeSet<u32>,cols:usize,rows:usize)->Vec<[usize;4]>{
 let at=|x:i32,y:i32|->Option<usize>{if x<0||y<0||x>=cols as i32||y>=rows as i32{None}else{Some(y as usize*cols+x as usize)}};let mut r=BTreeSet::new();
 for(t,v)in ids.iter().enumerate(){if !own.contains(v){continue}let tx=(t%cols)as i32;let ty=(t/cols)as i32;r.insert([t%cols*32,t/cols*32,(t%cols+1)*32,(t/cols+1)*32]);
  for(dx,dy)in[(-1,0),(1,0),(0,-1),(0,1)]{let Some(q)=at(tx+dx,ty+dy)else{continue};if !active.contains(&ids[q])||own.contains(&ids[q]){continue}let x=q%cols*32;let y=q/cols*32;r.insert(match(dx,dy){(-1,0)=>[x+30,y+2,x+32,y+30],(1,0)=>[x,y+2,x+2,y+30],(0,-1)=>[x+2,y+30,x+30,y+32],_=>[x+2,y,x+30,y+2]});}
  for vy in[ty,ty+1]{for vx in[tx,tx+1]{let pos=[(vx-1,vy-1),(vx,vy-1),(vx-1,vy),(vx,vy)];let slots:Option<Vec<_>>=pos.iter().map(|&(x,y)|at(x,y)).collect();let Some(slots)=slots else{continue};if !slots.iter().all(|q|active.contains(&ids[*q])){continue}for(&q,&(px,py))in slots.iter().zip(pos.iter()){if own.contains(&ids[q]){continue}let x=q%cols*32+if px==vx{0}else{30};let y=q/cols*32+if py==vy{0}else{30};r.insert([x,y,x+2,y+2]);}}}
 }r.into_iter().collect()
}
fn compose(control:&Sprite,ids:&[u32],s:usize,layers:&BTreeMap<(u32,usize),Layer>,allowed:&BTreeSet<u32>,pal:&[[u8;3];256],cols:usize)->(Sprite,Value){
 let(mut parts,mut retained,mut domains,mut used)=(Vec::new(),Vec::new(),Vec::new(),Vec::new());
 for(t,&asset)in ids.iter().enumerate(){if !allowed.contains(&asset){continue}let l=&layers[&(asset,s)];let n=parts.len();if let Some(d)=&l.retained{retained.push(RetainedOriginalPlacement{replacement_index:n,details:d.clone()});}if let Some(p)=&l.domain{domains.push(PaletteConstraintPlacement{replacement_index:n,palette:p.clone()});}
  parts.push(Replacement{image:l.image.clone(),position:[(t%cols*32)as i32,(t/cols*32)as i32],logical_size:[32,32]});used.push(json!({"slot":t,"asset":format!("{asset:05x}"),"position":[t%cols*32,t/cols*32],"component":l.record,"retained_cells":l.retained.as_ref().map(|d|d.cells()),"palette_domain":l.domain.as_ref().map(|d|d.indices())}));}
 let composed=TerrainHd::default().compose_with_palette_constraints(control,&parts,&retained,&domains,s,pal);assert!(composed.results.iter().all(|r|*r==OverlayResult::Applied),"{:?}",composed.results);let mut rc=0;let mut dc=0;
 for r in &retained{let p=&parts[r.replacement_index];for &[x,y]in r.details.cells(){for dy in 0..s{for dx in 0..s{let xx=(p.position[0]as usize+x as usize)*s+dx;let yy=(p.position[1]as usize+y as usize)*s+dy;assert_eq!(composed.image.pixels[yy*control.width+xx],control.pixels[yy*control.width+xx],"retained OriginalNx after every join");rc+=1;}}}}
 for d in &domains{let p=&parts[d.replacement_index];for y in 0..32*s{for x in 0..32*s{let i=(p.position[1]as usize*s+y)*control.width+p.position[0]as usize*s+x;assert!(d.palette.contains(composed.image.pixels[i]),"joined owner escaped original palette domain");dc+=1;}}}
 (composed.image,json!({"pre_blit":used,"retained_OriginalNx_samples":rc,"palette_domain_samples":dc}))
}


fn main(){
 let a:Vec<String>=std::env::args().collect();assert_eq!(a.len(),7,"DATA BASE OWN BANK CASES FRESH_OUTPUT");let contract=read(Path::new(&a[5]));let rows=contract["cases"].as_array().unwrap();assert_eq!(rows.len(),9);let own:BTreeSet<u32>=contract["own"].as_array().unwrap().iter().map(id).collect();assert_eq!(own,BTreeSet::from([0x10536,0x1053e,0x1054f,0x10561,0x1059e,0x105a7]));let cat=Catalog::open(&a[1]).unwrap();let pal=cat.palette().unwrap();let reg=Registry::base(&cat).unwrap();let mut verified=Vec::new();
 for row in rows{let mission:raptor_replica::content::ContentId=row["mission"].as_str().unwrap().into();let m=&reg.missions[&mission];assert_eq!(m.columns,9);let y0=row["window_row0"].as_u64().unwrap()as usize;let x0=row["window_column0"].as_u64().unwrap()as usize;assert!(x0+3<=9&&y0+3<=150);let mut actual=Vec::new();for slot in 0..9{let d=&row["authentic_original_definitions"][slot];let y=y0+slot/3;let x=x0+slot%3;let t=&m.tiles[m.layout[y*9+x]];assert_eq!(t.art.asset,Some(id(&d["asset"])));assert_eq!(t.health as i64,d["raw_health"].as_i64().unwrap().max(0));assert_eq!(t.reward as u64,d["reward"].as_u64().unwrap());let raw=cat.read(id(&d["FLATS_asset"])).unwrap();let off=d["FLATS_byte_offset"].as_u64().unwrap()as usize;assert_eq!(raptor_replica::assets::i16_at(&raw,off+4).unwrap()as i64,d["raw_health"].as_i64().unwrap());assert_eq!(raptor_replica::assets::i16_at(&raw,off+6).unwrap()as i64,d["reward"].as_i64().unwrap());actual.push(selected_art(t,true,false,false).asset.unwrap());}
 if !row["settled_event"].is_null(){let e=&row["settled_event"];let y=e["row"].as_u64().unwrap()as usize;let x=e["column"].as_u64().unwrap()as usize;let t=&m.tiles[m.layout[y*9+x]];let slot=e["slot"].as_u64().unwrap()as usize;assert!(t.health>0);assert_eq!(actual[slot],id(&e["definition"]["asset"]));let settled=selected_art(t,true,true,true).asset.unwrap();assert_eq!(settled,id(&e["definition"]["settled"]));actual[slot]=settled;verified.push(json!({"case":row["case_index"],"exact_Flats_selected_art_endpoint":true,"intact":e["definition"]["asset"],"settled":e["definition"]["settled"],"health":t.health,"reward":t.reward,"World":0}));}assert_eq!(actual,row["ordered_source_ids"].as_array().unwrap().iter().map(id).collect::<Vec<_>>());
 }
 for pair in contract["ordered_pairs"].as_array().unwrap(){let before=pair["before"].as_u64().unwrap()as usize;let after=pair["after"].as_u64().unwrap()as usize;let diffs=(0..9).filter(|i|rows[before]["ordered_source_ids"][*i]!=rows[after]["ordered_source_ids"][*i]).count();assert_eq!(diffs,1);}
 let literal=read(&Path::new(&a[2]).join("hd.json"));let mut native=BTreeMap::new();for s in literal["sequences"].as_array().unwrap(){for f in s["frames"].as_array().unwrap(){native.insert(s["base_asset"].as_u64().unwrap()as u32+f["frame"].as_u64().unwrap()as u32,f.clone());}}assert!(own.iter().all(|x|!native.contains_key(x)));let allsource:BTreeSet<u32>=rows.iter().flat_map(|r|r["ordered_source_ids"].as_array().unwrap()).map(id).collect();let foreign:BTreeSet<u32>=allsource.iter().copied().filter(|x|native.contains_key(x)).collect();let active:BTreeSet<u32>=foreign.union(&own).copied().collect();let fallback:BTreeSet<u32>=allsource.difference(&active).copied().collect();let pm=read(&Path::new(&a[3]).join("hd.json"));assert_eq!(pm["sequences"].as_array().unwrap().len(),6);for s in pm["sequences"].as_array().unwrap(){let asset=s["base_asset"].as_u64().unwrap()as u32;assert!(own.contains(&asset));assert_eq!(s["frame_count"],1);native.insert(asset,s["frames"][0].clone());}
 let bank=read(Path::new(&a[4]));let out=Path::new(&a[6]);assert!(!out.exists());fs::create_dir(out).unwrap();fs::create_dir(out.join("components")).unwrap();fs::create_dir(out.join("planes")).unwrap();fs::write(out.join("actual-palette-rgb.bin"),pal.iter().flat_map(|c|c.iter().copied()).collect::<Vec<_>>()).unwrap();let mut base=HdAssets::load_lazy(Path::new(&a[2]),&cat,None);let mut proposal=HdAssets::load_lazy(Path::new(&a[3]),&cat,None);assert!(base.diagnostics.is_empty()&&proposal.diagnostics.is_empty(),"base{:?} own{:?}",base.diagnostics,proposal.diagnostics);let mut layers=BTreeMap::new();let mut components=Vec::new();let mut stages=Vec::new();
 for &asset in &active{let source=cat.sprite(asset).unwrap();for scale in 1..5{let hd=if own.contains(&asset){&mut proposal}else{&mut base};let(image,retained,domain)=hd.terrain_sprite_with_palette(asset,scale,&pal).unwrap().unwrap();metadata_stage(&native[&asset],&retained,&domain);if own.contains(&asset){let r=bank.as_array().unwrap().iter().find(|r|id(&r["asset"])==asset).unwrap();assert_eq!(source.pixels,r["source"]["indices"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u16).collect::<Vec<_>>());let original=upscale(&source,scale).unwrap();let mut standalone=image.clone();if let Some(details)=&retained{for &[x,y]in details.cells(){for dy in 0..scale{let at=(y as usize*scale+dy)*standalone.width+x as usize*scale;standalone.pixels[at..at+scale].copy_from_slice(&original.pixels[at..at+scale]);}}}assert_eq!(standalone.pixels,bank_indices(&bank,asset,scale),"exact accepted G2 stage after trusted OriginalNx retention, never raw pre-retention comparison");stages.push(json!({"asset":format!("{asset:05x}"),"scale":scale,"retained_cells":retained.as_ref().map(|d|d.cells()),"restored_standalone_equals_accepted_G2_bank":true}));}let mut r=emit(&out.join("components"),&format!("{asset:05x}-s{scale}"),&image,&pal);r["asset"]=json!(format!("{asset:05x}"));r["scale"]=json!(scale);r["native_frame"]=native[&asset].clone();r["retained_cells"]=json!(retained.as_ref().map(|d|d.cells()));r["palette_domain"]=json!(domain.as_ref().map(|d|d.indices()));components.push(r.clone());layers.insert((asset,scale),Layer{image,retained,domain,record:r});}}
 let mut records=Vec::new();for row in rows{let case=row["case_index"].as_u64().unwrap();let ids:Vec<u32>=row["ordered_source_ids"].as_array().unwrap().iter().map(id).collect();let regions=support(&ids,&own,&active,3,3);let mut canvas=Canvas{scale:1,image:Sprite{width:96,height:96,pixels:vec![0;96*96]}};for(slot,&asset)in ids.iter().enumerate(){canvas.blit(&cat.sprite(asset).unwrap(),(slot%3*32)as i32,(slot/3*32)as i32);}
 for scale in 1..5{let original=upscale(&canvas.image,scale).unwrap();let(b,bi)=compose(&original,&ids,scale,&layers,&foreign,&pal,3);let(p,pi)=compose(&original,&ids,scale,&layers,&active,&pal,3);let(mut delta,mut outside,mut interiors,mut fallbackn)=(0usize,0usize,0usize,0usize);for i in 0..original.pixels.len(){let value=original.pixels[i];assert_eq!(class(b.pixels[i]),class(value));assert_eq!(class(p.pixels[i]),class(value));if value>=250{assert_eq!(b.pixels[i],value);assert_eq!(p.pixels[i],value);}let x=i%original.width;let y=i/original.width;let asset=ids[y/(32*scale)*3+x/(32*scale)];if own.contains(&asset){assert_eq!(b.pixels[i],value);}if fallback.contains(&asset){assert_eq!(b.pixels[i],value);assert_eq!(p.pixels[i],value);fallbackn+=1;}let allowed=regions.iter().any(|r|x>=r[0]*scale&&x<r[2]*scale&&y>=r[1]*scale&&y<r[3]*scale);if !allowed{assert_eq!(b.pixels[i],p.pixels[i]);outside+=1;}if foreign.contains(&asset)&&x%(32*scale)>=2*scale&&x%(32*scale)<30*scale&&y%(32*scale)>=2*scale&&y%(32*scale)<30*scale{assert_eq!(b.pixels[i],p.pixels[i]);interiors+=1;}if b.pixels[i]!=p.pixels[i]{assert!(allowed);delta+=1;}}
 let mut planes=serde_json::Map::new();for(role,img)in[("Original_joined_SourceNx",&original),("immutable_H5647_baseline",&b),("qualified6_proposal",&p)]{planes.insert(role.into(),emit(&out.join("planes"),&format!("case{case:02}-s{scale}-{role}"),img,&pal));}records.push(json!({"case_index":case,"scale":scale,"endpoint":row,"planes":planes,"baseline_inputs":bi,"proposal_inputs":pi,"support_rectangles":regions,"changed_samples":delta,"outside_support_samples_exact":outside,"foreign_interior_samples_exact":interiors,"Original_fallback_samples_exact":fallbackn,"all_SourceClasses_exact":true}));}}
 assert_eq!(stages.len(),24);assert_eq!(records.len(),36);assert!(base.diagnostics.is_empty()&&proposal.diagnostics.is_empty());let result=json!({"status":"ACTUAL_SOURCEG2_H5647_QUALIFIED_SIX_NINE_GENUINE_ENDPOINTS_FOUR_LEGAL_PAIRS_ALL4_SUCCESS","records":records,"components":components,"own_stage_checks":stages,"own":["10536","1053e","1054f","10561","1059e","105a7"],"Source_contract":contract,"verified_legal_settled_endpoints":verified,"fallback_ids":fallback.iter().map(|a|format!("{a:05x}")).collect::<Vec<_>>(),"World_calls":0,"not_all_callers_rendered":true,"diagnostics":[]});fs::write(out.join("ACTUAL-SIX-NINE-ENDPOINTS-FOUR-PAIRS-SOURCEG2-H5647.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("G2H5647 six9endpoints/4legalpairs/all4/108roleplanes;24ownstagechecks;0World");
}
